import './Veiculo.css';
import carros from './carros';
import { useParams } from 'react-router-dom';


function Veiculo(props) {
    const { id } = useParams();
    const carro = carros.find((item) => item.id === parseInt(id));

    if (!carro) {
    return <h2>Carro não encontrado!</h2>;
  }

 return(
    <div className="col"> 
        <div className="card shadow-sm"> 
            <img
                src={carro.imagem}  // <--- CORRIGIDO: Era 'img', mudou para 'imagem'
                className="bd-placeholder-img card-img-top" 
                alt={carro.titulo}
                width="100%" 
                height="300"
                style={{objectFit: "cover"}}
            />    
            <div className="card-body">                

                <p className="propriedades-veiculo"><b>{carro.titulo}</b></p> 

                {/* CORRIGIDO: Era 'props.preco', mudou para 'carro.preco' */}
                <p className="propriedades-veiculo"><b>R$ {carro.preco}</b></p>

            </div> 
        </div> 
    </div>

  );
}

export default Veiculo;
